solution.solution.cpp:
constexpr int cube(int n)
{
    return n * n * n;
}

unitTests:
static_assert(cube(3) == 27, "cube must be usable at compile time: mark it constexpr");
constexpr int atCompileTime{ cube(4) };

TEST("works at compile time") { CHECK_EQ(atCompileTime, 64); }
TEST("works at run time too") { int n{ 5 }; CHECK_EQ(cube(n), 125); CHECK_EQ(cube(-2), -8); }

